import sys


def check_digit(digits):
    total = 0
    for i, ch in enumerate(digits):
        if i % 2 == 0:
            total += int(ch) * 3
        else:
            total += int(ch)
    return 10 - total % 10


def fmt(digits):
    return f"756.{digits[3:7].zfill(4)}.{digits[7:11].zfill(4)}.{digits[11:].zfill(2)}"


def main():
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        digits = "".join(c for c in line if c.isdigit())
        if len(digits) != 12 and len(digits) != 13:
            print("ERROR")
            continue
        if len(digits) == 13 and digits.startswith("756"):
            if check_digit(digits[:12]) == int(digits[12]):
                print("VALID", fmt(digits))
            else:
                print("INVALID", check_digit(digits[:12]))
        elif len(digits) == 12 and digits.startswith("756"):
            correct_digit = check_digit(digits)
            print("COMPLETE", fmt(digits + str(correct_digit)))
        else:
            print("ERROR")


if __name__ == "__main__":
    main()
